 3	final class LcsRequest {
 4	    private final char[] longer;
 5	    private final char[] shorter;
 6	    private final Integer knownResult;
 7	
 8	    private LcsRequest(char[] longer, char[] shorter, Integer knownResult) {
 9	        this.longer = longer;
10	        this.shorter = shorter;
11	        this.knownResult = knownResult;
12	    }
13	
14	    static LcsRequest from(String first, String second) {
15	        Objects.requireNonNull(first, "first must not be null");
16	        Objects.requireNonNull(second, "second must not be null");
17	
18	        if (first.isEmpty() || second.isEmpty()) {
19	            return new LcsRequest(first.toCharArray(), second.toCharArray(), 0);
20	        }
21	
22	        if (first.equals(second)) {
23	            return new LcsRequest(first.toCharArray(), second.toCharArray(), first.length());
24	        }
25	
26	        char[] firstChars = first.toCharArray();
27	        char[] secondChars = second.toCharArray();
28	
29	        if (firstChars.length >= secondChars.length) {
30	            return new LcsRequest(firstChars, secondChars, null);
31	        }
32	
33	        return new LcsRequest(secondChars, firstChars, null);
34	    }
35	
36	    boolean hasKnownResult() {
37	        return knownResult != null;
38	    }
39	
40	    int knownResult() {
41	        return knownResult;
42	    }
43	
44	    char[] longer() {
45	        return longer;
46	    }
47	
48	    char[] shorter() {
49	        return shorter;
50	    }
51	}

 1	final class LcsSolver {
 2	    private final char[] longer;
 3	    private final char[] shorter;
 4	    private final int[] lengths;
 5	
 6	    LcsSolver(LcsRequest request) {
 7	        this.longer = request.longer();
 8	        this.shorter = request.shorter();
 9	        this.lengths = new int[shorter.length + 1];
10	    }
11	
12	    int solve() {
13	        for (char current : longer) {
14	            updateLengths(current);
15	        }
16	
17	        return lengths[shorter.length];
18	    }
19	
20	    private void updateLengths(char current) {
21	        int diagonal = 0;
22	
23	        for (int j = 1; j <= shorter.length; j++) {
24	            int previousRow = lengths[j];
25	
26	            lengths[j] = current == shorter[j - 1]
27	                ? diagonal + 1
28	                : Math.max(lengths[j], lengths[j - 1]);
29	            diagonal = previousRow;
30	        }
31	    }
32	}

